package app.chataibox.mobile;
import org.json.*;import okhttp3.*;import javax.crypto.Mac;import javax.crypto.spec.SecretKeySpec;import java.net.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.*;
/** End-to-end encrypted sync over an outbound socket. Server only routes opaque fragments. */
public final class RelayAgent implements AutoCloseable {
 public interface Repository{JSONArray merge(JSONArray records)throws Exception;}public interface Status{void update(boolean connected,String error);}
 private final JSONObject settings;private final String secret,url;private final Repository repository;private final Status status;private final Runnable synced;
 private final ScheduledExecutorService retry=Executors.newSingleThreadScheduledExecutor();private final ExecutorService io=new ThreadPoolExecutor(1,1,0,TimeUnit.SECONDS,new ArrayBlockingQueue<>(2),new ThreadPoolExecutor.AbortPolicy());private final Map<String,Partial> pending=new HashMap<>();private final Map<String,Long> seen=new HashMap<>();private volatile boolean closed=false;private volatile WebSocket socket;private final OkHttpClient client;
 private static class Partial{String from,id;StringBuilder data=new StringBuilder();long at=System.currentTimeMillis();}
 public static String roomId(String secret)throws Exception{if(!secret.matches("[a-f0-9]{64}"))throw new IOException("配对密钥无效");byte[] bytes=new byte[32];for(int i=0;i<32;i++)bytes[i]=(byte)Integer.parseInt(secret.substring(i*2,i*2+2),16);Mac mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(bytes,"HmacSHA256"));StringBuilder out=new StringBuilder();for(byte b:mac.doFinal("ChatAIBox relay channel v1".getBytes(StandardCharsets.UTF_8)))out.append(String.format(Locale.ROOT,"%02x",b));return out.toString();}
 public static String baseUrl(String text)throws Exception{URI u=new URI(text);if(!"https".equals(u.getScheme())||u.getHost()==null||u.getRawUserInfo()!=null||u.getRawQuery()!=null||u.getRawFragment()!=null)throw new IOException("转发服务地址必须是 HTTPS");return text.replaceAll("/+$","");}
 public RelayAgent(JSONObject settings,Repository repository,Status status,Runnable synced)throws Exception{this.settings=settings;this.secret=settings.getString("syncKey");this.url=baseUrl(settings.optString("relayUrl","")).replaceFirst("^https","wss")+"/relay";this.repository=repository;this.status=status;this.synced=synced;OkHttpClient.Builder builder=new OkHttpClient.Builder().connectTimeout(15,TimeUnit.SECONDS).readTimeout(0,TimeUnit.SECONDS).pingInterval(20,TimeUnit.SECONDS);String address=settings.optString("proxy");if(!address.isEmpty()){URI p=new URI(address);builder.proxy(new Proxy(Proxy.Type.HTTP,new InetSocketAddress(p.getHost(),p.getPort())));}client=builder.build();}
 public void start(){retry.execute(this::connect);}
 private void connect(){if(closed)return;Request.Builder request=new Request.Builder().url(url);String accessKey=settings.optString("relayAccessKey","");if(!accessKey.isEmpty())request.header("Authorization","Bearer "+accessKey);socket=client.newWebSocket(request.build(),new WebSocketListener(){
  public void onOpen(WebSocket ws,Response response){try{if(closed){ws.cancel();return;}ws.send(new JSONObject().put("type","join").put("role","phone").put("room",roomId(secret)).toString());}catch(Exception e){ws.cancel();}}
  public void onMessage(WebSocket ws,String text){if(closed||ws!=socket)return;try{JSONObject msg=new JSONObject(text);if(msg.optString("type").equals("joined")){status.update(true,"");return;}if(!msg.optString("type").equals("data"))return;String from=msg.getString("from"),id=msg.getString("id"),data=msg.getString("data");if(!from.matches("[a-f0-9-]{36}")||!id.matches("[a-f0-9-]{36}")||data.length()>48000)throw new IOException();String key=from+id;long now=System.currentTimeMillis();synchronized(pending){for(Iterator<Map.Entry<String,Partial>> it=pending.entrySet().iterator();it.hasNext();)if(now-it.next().getValue().at>180000)it.remove();Partial part=pending.get(key);if(part==null){if(pending.size()>=4)throw new IOException();part=new Partial();part.from=from;part.id=id;pending.put(key,part);}part.data.append(data);if(part.data.length()>96*1024*1024){pending.remove(key);throw new IOException();}if(msg.getBoolean("end")){pending.remove(key);final Partial complete=part;io.execute(()->handle(ws,complete));}}}catch(Exception e){status.update(true,"收到无效的加密同步请求，已拒绝");}}
  public void onFailure(WebSocket ws,Throwable error,Response response){disconnected(ws,response!=null&&response.code()==401?"服务器访问密钥无效或未填写，请更新两端同步设置":"转发连接断开，正在自动重连");}
  public void onClosed(WebSocket ws,int code,String reason){disconnected(ws);}
  public void onClosing(WebSocket ws,int code,String reason){ws.close(code,reason);}
 });}
 private void disconnected(WebSocket ws){disconnected(ws,"转发连接断开，正在自动重连");}
 private void disconnected(WebSocket ws,String message){if(closed||ws!=socket)return;synchronized(pending){pending.clear();}status.update(false,message);try{retry.schedule(this::connect,3,TimeUnit.SECONDS);}catch(RejectedExecutionException ignored){}}
 private void handle(WebSocket ws,Partial part){try{JSONObject request=SyncCrypto.open(new JSONObject(part.data.toString()),secret);long now=System.currentTimeMillis();for(Iterator<Map.Entry<String,Long>> it=seen.entrySet().iterator();it.hasNext();)if(now-it.next().getValue()>300000)it.remove();if(!request.optString("kind").equals("request")||!part.id.equals(request.optString("id"))||Math.abs(now-request.getLong("at"))>300000||seen.containsKey(part.id)||seen.size()>=10000)throw new IOException();seen.put(part.id,now);JSONArray records=repository.merge(request.getJSONArray("records")),inventory=request.optJSONArray("known");if(inventory!=null){if(inventory.length()>30000)throw new IOException();Map<String,String> known=new HashMap<>();for(int i=0;i<inventory.length();i++){JSONArray pair=inventory.getJSONArray(i);known.put(pair.getString(0),pair.getString(1));}JSONArray delta=new JSONArray();for(int i=0;i<records.length();i++){JSONObject row=records.getJSONObject(i);if(!row.getString("rev").equals(known.get(row.getString("id"))))delta.put(row);}records=delta;}
 JSONObject response=new JSONObject().put("kind","response").put("id",part.id).put("at",System.currentTimeMillis()).put("records",records);String encrypted=SyncCrypto.seal(response,secret).toString();for(int offset=0;offset<encrypted.length();offset+=48000){while(!closed&&ws==socket&&ws.queueSize()>512*1024)Thread.sleep(10);if(closed||ws!=socket)return;if(!ws.send(new JSONObject().put("type","data").put("to",part.from).put("id",part.id).put("data",encrypted.substring(offset,Math.min(offset+48000,encrypted.length()))).put("end",offset+48000>=encrypted.length()).toString()))return;}synced.run();status.update(true,"");
 }catch(Exception e){status.update(true,"同步请求校验或保存失败，请检查配对密钥与手机存储");}}
 @Override public void close(){closed=true;if(socket!=null)socket.cancel();retry.shutdownNow();io.shutdownNow();client.dispatcher().executorService().shutdown();client.connectionPool().evictAll();synchronized(pending){pending.clear();}}
}
